import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    lengths = list(map(int, data[1:1+n]))

    # Check if it's possible
    total = 0.0
    for length in lengths:
        total += 1.0 / (2 ** length)

    if total > 1.0:
        print("NO")
        return

    # Construct words
    used_prefixes = set()
    words = []

    for length in lengths:
        # Try all binary strings of this length
        for binary in range(2 ** length):
            binary_str = bin(binary)[2:].zfill(length)

            # Check if this string is valid
            valid = True
            for prefix in used_prefixes:
                if binary_str.startswith(prefix):
                    valid = False
                    break

            if valid:
                # Add all prefixes of this string to used_prefixes
                for i in range(length):
                    used_prefixes.add(binary_str[:i+1])
                words.append(binary_str)
                break

    print("YES")
    for word in words:
        print(word)

if __name__ == "__main__":
    solve()
"}

