def modinv(a, m):
    """Compute modular inverse using Fermat's little theorem."""
    return pow(a, m - 2, m)

def solve():
    MOD = 998244353
    n = int(input())

    # Count occurrences of each item
    cnt = {}
    # Sum of 1/k_i for each item
    sum_reciprocal = {}

    for _ in range(n):
        parts = list(map(int, input().split()))
        k_i = parts[0]
        items = parts[1:]

        # Update counts
        for item in items:
            cnt[item] = cnt.get(item, 0) + 1

        # Update reciprocal sum
        reciprocal = modinv(k_i, MOD)
        for item in items:
            sum_reciprocal[item] = sum_reciprocal.get(item, 0) + reciprocal

    # Compute numerator and denominator
    numerator = 0
    denominator = n * n % MOD

    for item in cnt:
        numerator = (numerator + cnt[item] * sum_reciprocal[item]) % MOD

    # Compute result: numerator / denominator mod MOD
    result = (numerator * modinv(denominator, MOD)) % MOD
    print(result)

solve()
"}

