import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    # Read the matrix
    u = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(n)]
        u.append(row)

    # Precompute cost[a][b] for 1 <= a <= b <= n
    cost = [[0] * (n + 1) for _ in range(n + 1)]
    for a in range(1, n + 1):
        for b in range(a, n + 1):
            # Compute cost for gondola containing people a to b
            total = 0
            for x in range(a - 1, b):
                for y in range(x + 1, b):
                    total += u[x][y]
            cost[a][b] = total

    # DP table
    INF = float('inf')
    dp = [[INF] * (k + 1) for _ in range(n + 1)]

    # Base case: 1 gondola for first i people
    for i in range(1, n + 1):
        dp[i][1] = cost[1][i]

    # Fill DP table
    for j in range(2, k + 1):
        for i in range(j, n + 1):
            # Try all possible splits
            for m in range(j - 1, i):
                dp[i][j] = min(dp[i][j], dp[m][j - 1] + cost[m + 1][i])

    print(dp[n][k])

if __name__ == "__main__":
    solve()
"}

