    boys = list(map(int, input().split()))
    girls = list(map(int, input().split()))

    # Count occurrences of each boy and each girl
    count_boy = {}
    count_girl = {}
    for boy in boys:
        count_boy[boy] = count_boy.get(boy, 0) + 1
    for girl in girls:
        count_girl[girl] = count_girl.get(girl, 0) + 1

    # Calculate same_boy and same_girl
    same_boy = 0
    for cnt in count_boy.values():
        same_boy += cnt * (cnt - 1) // 2

    same_girl = 0
    for cnt in count_girl.values():
        same_girl += cnt * (cnt - 1) // 2

    # Calculate total pairs and valid pairs
    total = k * (k - 1) // 2
    valid = total - same_boy - same_girl

    print(valid)
