import sys

def solve():
    s = sys.stdin.readline().strip()

    # Start from the end and work backwards
    result = []

    for i in range(len(s) - 1, -1, -1):
        char = s[i]

        # If result is empty, add the character
        if not result:
            result.append(char)
        else:
            # If current character is greater than the last in result, add to front
            if char > result[-1]:
                result.append(char)
            elif char == result[-1]:
                # If equal, add to front only if there are enough characters left
                # to fill the rest of the result
                if len(result) + (len(s) - i - 1) == len(result) + 1:
                    # There are enough characters left
                    result.append(char)
                else:
                    # Not enough characters left, skip
                    pass
            else:
                # If smaller, skip
                pass

    # Reverse to get the correct order
    result.reverse()

    print(''.join(result))

if __name__ == "__main__":
    solve()
"}

