import sys
import heapq

def dijkstra(n, adj, start):
    """Find shortest paths from start to all other nodes"""
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    heap = [(0, start)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue

        for v, w in adj[u]:
            # From u to v, cost is w^2
            new_dist = dist[u] + w * w
            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(heap, (new_dist, v))

    return dist

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    adj = [[] for _ in range(n + 1)]

    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        adj[u].append((v, w))
        adj[v].append((u, w))

    dist = dijkstra(n, adj, 1)

    for i in range(1, n + 1):
        if i == 1:
            print(0, end=' ')
        else:
            print(dist[i], end=' ')

    print()

