import bisect

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    results = []

    for _ in range(t):
        n = int(next(it))
        next_vals = list(map(int, [next(it) for _ in range(n)]))

        # Create an array to store the permutation
        p = [0] * n

        # We'll use a segment tree to find available positions
        # Available positions are initially 0 to n-1

        # Find the index of the maximum element
        max_index = -1
        for i in range(n):
            if next_vals[i] == n + 1:
                max_index = i
                break

        if max_index == -1:
            # No element is the maximum, this is impossible
            results.append("-1")
            continue

        # Place the maximum element at the end
        p[n - 1] = n
        available = list(range(n - 1))

        # Iterate from n-1 down to 1 (excluding the maximum element)
        for val in range(n - 1, 0, -1):
            # Find where to place val
            idx = -1
            for i in range(n):
                if next_vals[i] == val + 1 and p[i] == val:
                    idx = i
                    break

            if idx == -1:
                # No constraint, place at the beginning of available positions
                if available:
                    pos = available[0]
                else:
                    pos = n - 1
            else:
                # Place before the element at index idx
                pos_idx = bisect.bisect_left(available, idx)
                if pos_idx == 0:
                    pos = available[0]
                else:
                    pos = available[pos_idx - 1]

            available.pop(available.index(pos))
            p[pos] = val

        # Check if all next values are satisfied
        valid = True
        for i in range(n):
            val = next_vals[i]
            if val == -1:
                continue

            # Find the next greater element
            next_greater = -1
            for j in range(i + 1, n):
                if p[j] > p[i]:
                    next_greater = j + 1  # convert to 1-indexed
                    break

            if next_greater != val:
                valid = False
                break

        if valid:
            results.append(' '.join(map(str, p)))
        else:
            results.append("-1")

    sys.stdout.write("\n".join(results))

