        pi = int(input[3 + 2*i])
        vol = 1 if ti == 1 else 2
        vehicles.append((ti, pi, i + 1, vol))

    # dp[vol] = (max_capacity, selected_indices)
    dp = [(-1, []) for _ in range(v + 1)]
    dp[0] = (0, [])

    for ti, pi, idx, vol in vehicles:
        for j in range(v, vol - 1, -1):
            if dp[j - vol][0] != -1:
                new_capacity = dp[j - vol][0] + pi
                new_indices = dp[j - vol][1] + [idx]
                if dp[j][0] < new_capacity:
