from collections import deque

def bfs(start, tree, n):
    dist = [-1] * (n + 1)
    dist[start] = 0
    q = deque([start])
    while q:
        u = q.popleft()
        for v in tree[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)
    farthest_node = max(range(1, n + 1), key=lambda x: dist[x])
    return farthest_node, dist[farthest_node]

