    """Find the maximum overlap where suffix of a matches prefix of b."""
    max_overlap = 0
    for i in range(min(len(a), len(b))):
        if a[-(i+1):] == b[:i+1]:
            max_overlap = i + 1
    return max_overlap

def shortest_superstring(s1, s2, s3):
    # Consider all permutations of the three strings
    permutations = [
        (s1, s2, s3),
        (s1, s3, s2),
        (s2, s1, s3),
        (s2, s3, s1),
        (s3, s1, s2),
        (s3, s2, s1)
    ]

    min_length = float('inf')

    for perm in permutations:
        a, b, c = perm

        # Merge a and b with maximum overlap
        overlap_ab = max_overlap(a, b)
        merged_ab = a + b[overlap_ab:]

        # Merge merged_ab with c with maximum overlap
        overlap_ab_c = max_overlap(merged_ab, c)
