import sys

def is_touchy_feely_palindrome(s):
    # Check if the string is a palindrome
    is_palindrome = s == s[::-1]

    # Check if the string contains the digit 7
    contains_7 = '7' in s

    # Touchy-Feely Palindromes: strings that are palindromes OR contain the digit 7
    return is_palindrome or contains_7

