vehicles = []
for i in range(n):
    t, p = map(int, input().split())
    vehicles.append((t, p, i + 1))  # Store index

# dp[i] = maximum carrying capacity for volume i
# We'll use a list of tuples (capacity, selected_indices)
dp = [(-1, [])] * (v + 1)
dp[0] = (0, [])

for t, p, idx in vehicles:
    # Update from back to front to avoid reusing the same vehicle
    for vol in range(v, -1, -1):
        if dp[vol][0] != -1:
            if t == 1:
                new_vol = vol + 1
                if new_vol <= v:
                    new_cap = dp[vol][0] + p
                    new_indices = dp[vol][1] + [idx]
                    if dp[new_vol][0] < new_cap:
                        dp[new_vol] = (new_cap, new_indices)
            else:  # t == 2
                new_vol = vol + 2
                if new_vol <= v:
                    new_cap = dp[vol][0] + p
                    new_indices = dp[vol][1] + [idx]
                    if dp[new_vol][0] < new_cap:
                        dp[new_vol] = (new_cap, new_indices)

max_capacity = max(dp[i][0] for i in range(v + 1))
selected_indices = dp[dp.index(max_capacity)][1]

print(max_capacity)
print(' '.join(map(str, selected_indices)))
