def solve():
    n, m, x, y = map(int, input().split())
    grid = [list(input().strip()) for _ in range(n)]

    # Precompute cost to make each column all white or all black
    column_white_cost = [0] * m
    column_black_cost = [0] * m

    for col in range(m):
        white = 0
        black = 0
        for row in range(n):
            if grid[row][col] == '.':
                white += 1
            else:
                black += 1
        column_white_cost[col] = black
        column_black_cost[col] = white

    # DP: dp[i][color] = minimum cost to process first i columns
    # where color = 0 for white, 1 for black
    # We need to ensure that groups are valid

    # dp[i][c][g] = minimum cost to process first i columns,
    # where we have g columns in the current group of color c

    # Initialize: no columns processed
    dp = [[[float('inf')] * 2 for _ in range(y + 1)] for _ in range(m + 1)]

    # We can start with a group of size 1
    for color in range(2):
        for size in range(1, y + 1):
            dp[0][size][color] = column_white_cost[0] if color == 0 else column_black_cost[0]

    # Process each column
    for i in range(1, m):
        original_color = 0 if grid[0][i] == '.' else 1

        # Continue the current group
        for size in range(1, y):
            for color in range(2):
                if size > 0:
                    prev_size = size - 1
                    prev_cost = dp[i-1][prev_size][color]
                    cost_i = 0 if original_color == color else 1
                    dp[i][size][color] = min(dp[i][size][color], prev_cost + cost_i)

        # Start a new group
        for prev_size in range(x, y):
            for prev_color in range(2):
                for color in range(2):
                    # Check if we can start a new group
                    if prev_size >= x and prev_size <= y:
                        cost_i = 0 if original_color == color else 1
                        dp[i][1][color] = min(dp[i][1][color], dp[i-1][prev_size][prev_color] + cost_i)

    # Find the minimum answer
    answer = float('inf')
    for size in range(x, y + 1):
        for color in range(2):
            answer = min(answer, dp[m-1][size][color])

    print(answer)

solve()
