import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    # Read the matrix
    u = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(n)]
        u.append(row)

    # Precompute unfamiliar values for consecutive people
    # unfamiliar[i][j] = sum of u[x][y] for x in range(i, j+1), y in range(i, j+1)
    unfamiliar = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(i, n):
            # Compute unfamiliar value for people i to j
            val = 0
            for x in range(i, j + 1):
                for y in range(x, j + 1):
                    val += u[x][y]
            unfamiliar[i][j] = val

    # DP: dp[i][j] = min unfamiliar value with i gondolas and j people remaining
    # Initialize
    INF = 10**18
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][n] = 0

    for gondolas in range(1, k + 1):
        for remaining in range(1, n + 1):
            # Try all possible group sizes
            for q in range(1, remaining + 1):
                # Take last q people
                dp[gondolas][remaining] = min(
                    dp[gondolas][remaining],
                    dp[gondolas - 1][remaining - q] + unfamiliar[remaining - q][remaining - 1]
                )

    print(dp[k][n])

if __name__ == "__main__":
    solve()
