import sys

def is_regular_bracket_sequence(s):
    open_count = 0
    close_count = 0

    for char in s:
        if char == '(':
            open_count += 1
        elif char == ')':
            close_count += 1
        else:  # char == '?'
            # Treat '?' as '(' if we need more '('
            if open_count < close_count:
                open_count += 1
            # Treat '?' as ')' if we need more ')'
            elif open_count > close_count:
                close_count += 1
            # If open_count == close_count, we can treat '?' as either, but we'll treat as '('
            else:
                open_count += 1

        # Check if at this point we have more closing brackets than opening
        if close_count > open_count:
            return False

    # At the end, we should have equal numbers of '(' and ')'
    return open_count == close_count

def solve():
    data = sys.stdin.read().strip().split()
    t = int(data[0])
    results = []

    for i in range(1, t + 1):
        s = data[i]
        if is_regular_bracket_sequence(s):
            results.append("YES")
        else:
            results.append("NO")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
