def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    s = next(it)

    # Track which characters are removed
    removed = [False] * n

    for _ in range(m):
        l = int(next(it)) - 1  # 0-indexed
        r = int(next(it)) - 1
        c = next(it)

        # Mark characters to remove
        for i in range(l, r + 1):
            if s[i] == c:
                removed[i] = True

    # Build result
    result = []
    for i in range(n):
        if not removed[i]:
            result.append(s[i])

    sys.stdout.write(''.join(result))

if __name__ == '__main__':
    solve()
