import sys

def count_subarrays_with_at_least_k_equal(n, k, a):
    freq = {}
    left = 0
    result = 0

    for right in range(n):
        # Add current element to frequency map
        freq[a[right]] = freq.get(a[right], 0) + 1

        # Check if current element reaches count k
        if freq[a[right]] == k:
            # Count subarrays ending at right that start from left to right
            result += (right - left + 1)

        # Move left pointer to maintain window
        while left <= right and freq[a[left]] > k:
            freq[a[left]] -= 1
            if freq[a[left]] == 0:
                del freq[a[left]]
            left += 1

    return result

