import sys

def is_regular_bracket_sequence(s):
    """Check if a bracket sequence can be made regular."""
    open_count = 0
    close_count = 0
    question_count = 0

    # Count characters
    for char in s:
        if char == '(':
            open_count += 1
        elif char == ')':
            close_count += 1
        else:  # char == '?':
            question_count += 1

    # Check if we can balance
    if open_count > close_count or close_count > open_count:
