def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    # Build adjacency list
    adj = [[] for _ in range(N + 1)]
    for _ in range(M):
        a = int(next(it))
        b = int(next(it))
        c = int(next(it))
        adj[a].append((b, c))
        adj[b].append((a, c))

    # Check for contradictions
    visited = [False] * (N + 1)
    result = [0.0] * (N + 1)

    def dfs(u, parent, val):        # val is the value of the parent
        visited[u] = True
        result[u] = val

        for v, color in adj[u]:
            if v == parent:
                continue
            if not visited[v]:
                if color == 1:  # black edge
                    dfs(v, u, 1 - val)
                else:  # red edge
                    dfs(v, u, 2 - val)
            else:
                # Check consistency
                expected = result[u] + result[v]
                if color == 1:
                    if abs(expected - 1) > 1e-9:
                        return False
                else:
                    if abs(expected - 2) > 1e-9:
                        return False
        return True

    for u in range(1, N + 1):
        if not visited[u]:
            if not dfs(u, -1, 0.0):
                print("NO")
                return

    # Check if all constraints are satisfied
    for u in range(1, N + 1):
        for v, color in adj[u]:
            if u < v:  # avoid duplicate checks
                expected = result[u] + result[v]
                if color == 1:
                    if abs(expected - 1) > 1e-9:
                        print("NO")
                        return
                else:
                    if abs(expected - 2) > 1e-9:
                        print("NO")
                        return

    print("YES")
    print(" ".join(f"{x:.10f}" for x in result[1:N+1]))

