def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Determine farthest positions
    if n % 2 == 0:
        farthest_odd = n - 1
        farthest_even = n
    else:
        farthest_odd = n
        farthest_even = n - 1

    # Calculate minimum moves for each k
    result = []
    for k in range(1, n):
        total_moves = 0
        for i in range(1, k + 1):
            if a[i - 1] == 0:
                continue
            if i % 2 == 1:
                # Odd position
                if farthest_odd < k:
                    # Can't move to any odd position > k
                    # Need to move to farthest_odd first, then to some even position
                    # Actually, we need to move to some odd position > k
                    # If farthest_odd <= k, we can't reach any odd > k
                    # So we need to move to farthest_odd and then to farthest_even
                    # Distance from i to farthest_odd: (farthest_odd - i) // 2
                    # Distance from farthest_odd to farthest_even: (farthest_even - farthest_odd) // 2
                    distance = ((farthest_odd - i) // 2) + ((farthest_even - farthest_odd) // 2)
                else:
                    distance = (farthest_odd - i) // 2
            else:
                # Even position
                if farthest_even < k:
                    distance = ((farthest_even - i) // 2) + ((farthest_odd - farthest_even) // 2)
                else:
                    distance = (farthest_even - i) // 2

            total_moves += distance * a[i - 1]
        result.append(total_moves)

    sys.stdout.write("\n".join(map(str, result)))

