def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    h = int(next(it))

    a = [int(next(it)) for _ in range(m)]  # front view
    b = [int(next(it)) for _ in range(n)]  # left view

    # Read top view
    top = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(m)]
        top.append(row)

    # Initialize matrix with zeros
    matrix = [[0] * m for _ in range(n)]

