def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        adj[u].append((v, w))
        adj[v].append((u, w))

    # For each city t, find the minimum cost to reach t using exactly two roads
    # We can reach t from 1 either directly (cost 0) or via an intermediate city b
    result = [0] * (n + 1)

    for t in range(1, n + 1):
        # If we can reach t directly from 1, cost is 0
        # Otherwise, we need to find intermediate city b
        min_cost = float('inf')

        # Check direct road
        for neighbor, w in adj[t]:
            if neighbor == 1:
                min_cost = 0
                break

        if min_cost == float('inf'):
            # Need to find intermediate city b such that 1-b and b-t exist
            for b in range(1, n + 1):
                # Check if b is adjacent to t
                if t in [v for v, w in adj[b]]:
                    # Check if 1 is adjacent to b
                    if 1 in [v for v, w in adj[b]]:
                        # Calculate cost from 1 to b to t
                        # We need the weight of the road from 1 to b and from b to t
                        # But wait, there could be multiple roads from 1 to b
                        # We need the one with minimum weight?
                        # Actually, we need the exact road weights
                        # Let's find the specific weights
                        w1b = None
                        wbt = None

                        for v, w in adj[b]:
                            if v == t:
                                wbt = w
                        for v, w in adj[1]:
                            if v == b:
                                w1b = w

                        if w1b is not None and wbt is not None:
                            cost = (w1b + wbt) ** 2
                            if cost < min_cost:
                                min_cost = cost

        result[t] = min_cost if min_cost != float('inf') else -1

    # Print results for cities 1 to n
    print(' '.join(str(result[t]) for t in range(1, n + 1)))

if __name__ == '__main__':
