import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    k = int(data[2])

    # Find connected components using Union-Find
    parent = list(range(n + 1))  # 1-indexed

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # Path compression
            x = parent[x]
        return x

    def union(x, y):
        px = find(x)
        py = find(y)
        if px != py:
            parent[py] = px

    for i in range(3, 3 + 2 * m, 2):
        a = int(data[i])
        b = int(data[i + 1])
        union(a, b)

    # Find component sizes
    components = {}
    for i in range(1, n + 1):
        root = find(i)
        if root not in components:
            components[root] = 0
        components[root] += 1

    sizes = list(components.values())
    c = len(sizes)

    # Calculate answer
    product = 1
    for s in sizes:
        product = (product * s) % k

    if c == 1:
        # Already connected, need to add 0 links
        answer = 1
