def solve():
    n, w, h = map(int, input().split())
    envelopes = []
    for i in range(n):
        wi, hi = map(int, input().split())
        if wi > w and hi > h:
            envelopes.append((wi, hi, i + 1))  # Store 1-indexed envelope number

    if not envelopes:
        print(0)
        return

    # Sort by width, then by height
    envelopes.sort()

    # DP: dp[i] = (max_chain_length, previous_index)
    dp = [(1, -1) for _ in range(len(envelopes))]

    for i in range(len(envelopes)):
        for j in range(i):
            # Check if envelope j can precede envelope i
            if envelopes[j][0] < envelopes[i][0] and envelopes[j][1] < envelopes[i][1]:
                if dp[j][0] + 1 > dp[i][0]:
                    dp[i] = (dp[j][0] + 1, j)

    # Find the envelope with maximum chain length
    max_len = 0
    best_idx = 0
    for i in range(len(envelopes)):
        if dp[i][0] > max_len:
            max_len = dp[i][0]
            best_idx = i

    # Reconstruct the chain
    chain = []
    current = best_idx
    while current != -1:
        chain.append(envelopes[current][2])  # Append envelope number
        current = dp[current][1]

    # The chain is constructed in reverse order (smallest to largest)
    chain.reverse()

    print(max_len)
    print(' '.join(map(str, chain)))

