def max_overlap(s1, s2):
    """Find the maximum overlap where suffix of s1 matches prefix of s2"""
    max_ov = 0
    for i in range(1, min(len(s1), len(s2)) + 1):
        if s1[-i:] == s2[:i]:
            max_ov = i
    return max_ov

def merge(s1, s2):
    """Merge two strings with maximum overlap"""
    ov = max_overlap(s1, s2)
    return s1 + s2[ov:]

def shortest_superstring(s1, s2, s3):
    # First, check if one string is already a superstring of the others
    candidates = sorted([s1, s2, s3], key=len, reverse=True)
    longest = candidates[0]

    # Check if the other two are substrings of the longest
    indices = []
    for s in candidates[1:]:
        if s in longest:
            indices.append(len(candidates[0]) - longest.find(s))

    # If both are substrings, return the length of the longest
    if len(indices) == 2:
        return len(candidates[0])

    # If one is a substring, find the optimal merging of the other two
    elif indices:
        min_len = float('inf')
        for order in [(candidates[1], candidates[2]),
                      (candidates[2], candidates[1])]:
            merged = merge(order[0], order[1])
            final_len = len(candidates[0]) - indices[0] + len(merged)
            min_len = min(min_len, final_len)
        return min_len

    else:
        # No substring relationships, just merge optimally
        return min(len(candidates[0] + candidates[1] + candidates[2]),
                   len(candidates[0] + merge(candidates[1], candidates[2])),
                   len(merge(candidates[0], candidates[1]) + candidates[2]))

# Read input
s1 = input().strip()
s2 = input().strip()
s3 = input().strip()

# Calculate and print result
length = shortest_superstring(s1, s2, s3)
print(length)
