    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    x = int(data[2])
    y = int(data[3])

    # Read the grid
    grid = []
    idx = 4
    for _ in range(n):
        row = data[idx]
        grid.append(row)
        idx += 1

    # Initialize DP
    # dp[i][c][w]: min repaints for first i columns, ending with color c (0=white, 1=black), width w
    INF = float('inf')
    dp = [[[INF] * (y + 1) for _ in range(2)] for _ in range(m + 1)]

    # Base case: first column
    for c in range(2):
        for w in range(1, y + 1):
            if w == 1:
                # We can start a new group at column 1
                if c == 0:
                    # White at column 1
                    cost = 0 if grid[0][0] == '.' else 1
                else:
                    # Black at column 1
                    cost = 0 if grid[0][0] == '#' else 1
                dp[1][c][w] = cost
            else:
                # width > 1, not valid
                pass

    # Fill DP
    for i in range(2, m + 1):
        for c in range(2):
            for w in range(1, y + 1):
                if w > 1:
                    # Extend previous group
                    # Previous state: column i-1, color c, width w-1
                    if dp[i-1][c][w-1] != INF:
                        cost = 0
                        if c == 0 and grid[i-1][c] != '.':
                            cost += 1
                        elif c == 1 and grid[i-1][c] != '#':
                            cost += 1
                        dp[i][c][w] = dp[i-1][c][w-1] + cost
                else:  # w == 1
                    # Start new group at column i with color c
                    # Previous state: column i-1, color d != c, width in [x, y]
                    min_cost = INF
                    for d in range(2):
                        if d == c:
                            continue
                        # Check if we can start a new group at column i
                        # Columns 1..i-1 must be consistent with color d and width w_prev
                        # Actually, we just need to ensure the previous width is within [x, y]
                        for w_prev in range(x, y + 1):
                            if dp[i-1][d][w_prev] != INF:
                                # Start new group at column i with color c
                                # cost = 1 if we need to repaint column i
                                cost = 0 if c == 0 and grid[i-1][c] == '.' else 1
                                # Actually, we need to check if column i matches c
                                cost = 0 if c == 0 and grid[i-1][c] == '.' else 1
                                dp[i][c][w] = min(dp[i][c][w], dp[i-1][d][w_prev] + cost)

    # Find minimum among all valid endings
    result = INF
    for c in range(2):
        for w in range(x, y + 1):
            result = min(result, dp[m][c][w])

    print(result)

if __name__ == "__main__":
    solve()
