import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    m = int(data[0])
    s = data[1] if len(data) > 1 else ""
    n = len(s)

    result = []
    pos = 0

    while True:
        # We need to cover from pos to some end position
        # We select the smallest character in [pos, min(pos + m - 1, n)]
        # but we need to ensure we don't overshoot
        if pos + m - 1 > n:
            # Last selection
            end = n
        else:
            end = min(pos + m - 1, n)

        min_char = 'z'
        min_idx = -1

        for i in range(pos, end):
            if s[i] < min_char:
                min_char = s[i]
                min_idx = i

        result.append(min_char)

        # Move to the next position after the selected one
        pos = min_idx + 1

        # If we've covered the entire string, break
        if pos >= n:
            break

    print(''.join(result))

if __name__ == "__main__":
