import sys

def can_reconstruct(lengths):
    """Check if we can reconstruct words with given lengths such that no word is a prefix of another."""
    # Count words of length 1
    count_length_1 = lengths.count(1)

    # If more than one word of length 1, impossible
    if count_length_1 > 1:
        return False, []

    # Track used prefixes
    used_prefixes = set()

    # Construct words
    words = []

    # Handle words of length 1
    if count_length_1 == 1:
        # We can choose either "0" or "1"
        words.append("0")
        used_prefixes.add("0")

    # Handle words of length > 1
    for length in lengths:
        if length == 1:
            continue  # Already handled

        # Try to construct a word of this length
        constructed = False

        # Try all possible binary strings of this length
        for bits in range(2 ** length):
            word = format(bits, '0{}b'.format(length))

            # Check if this word is valid (no prefix in used_prefixes)
            valid = True
            for i in range(1, length):
                if word[:i] in used_prefixes:
                    valid = False
